-- Autonomous township remaining-gap repair: MMR004 / Chin
-- Project locghyuranqaqsnbxflc; generated 2026-07-24.
-- One-time repair: existing geom only; no inserts or metadata changes.
BEGIN;
SET LOCAL statement_timeout = '15min';
SET LOCAL lock_timeout = '30s';

CREATE TEMP TABLE _autonomous_fill_results (
    township_id bigint PRIMARY KEY,
    canonical_name text NOT NULL,
    mimu_pcode text NOT NULL,
    status text NOT NULL CHECK (
        status IN ('updated', 'already_covered', 'numerical_residue', 'failed')
    ),
    best_candidate_id bigint,
    best_score double precision,
    second_score double precision,
    area_added_m2 double precision NOT NULL DEFAULT 0,
    new_overlap_m2 double precision NOT NULL DEFAULT 0,
    reason text NOT NULL
) ON COMMIT DROP;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6712;
    v_expected_name constant text := 'တွန်းဇံမြို့နယ်';
    v_mimu_pcode constant text := 'MMR004005';
    v_expected_parent_id constant bigint := 6717;
    v_expected_state_id constant bigint := 6744;
    v_expected_geom_hash constant text := 'e1c20d8cdb5683e58184327453045f4b';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"တွန်းဇံမြို့နယ်","centroid":{"coordinates":[93.77109250564591,23.7974188],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996872","geometry_source":null,"id":6712,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Tonzan;Ton Zang","area_m2":3475372994.349399,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13215,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996872","id":5192,"is_primary":true,"language_code":"und","name":"တွန်းဇံမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996872","raw_id":11208,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13215,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996872","id":5193,"is_primary":true,"language_code":"en","name":"Tonzang Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996872","raw_id":11208,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13215,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996872","id":5194,"is_primary":true,"language_code":"my","name":"တွန်းဇံမြို့နယ်","name_type":"o