-- Autonomous township remaining-gap repair: MMR012 / Rakhine
-- Project locghyuranqaqsnbxflc; generated 2026-07-24.
-- One-time repair: existing geom only; no inserts or metadata changes.
BEGIN;
SET LOCAL statement_timeout = '15min';
SET LOCAL lock_timeout = '30s';

CREATE TEMP TABLE _autonomous_fill_results (
    township_id bigint PRIMARY KEY,
    canonical_name text NOT NULL,
    mimu_pcode text NOT NULL,
    status text NOT NULL CHECK (
        status IN ('updated', 'already_covered', 'numerical_residue', 'failed')
    ),
    best_candidate_id bigint,
    best_score double precision,
    second_score double precision,
    area_added_m2 double precision NOT NULL DEFAULT 0,
    new_overlap_m2 double precision NOT NULL DEFAULT 0,
    reason text NOT NULL
) ON COMMIT DROP;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 5091;
    v_expected_name constant text := 'မာန်အောင်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR012012';
    v_expected_parent_id constant bigint := 7108;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'ac627977735b56eb01d3f820df969859';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မာန်အောင်မြို့နယ်","centroid":{"coordinates":[93.63187888087697,18.7941078],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996745","geometry_source":null,"id":5091,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Munaung;Manaung","area_m2":474972432.27642316,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":226,"is_primary":true,"language_code":"und","name":"မာန်အောင်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":227,"is_primary":true,"language_code":"en","name":"Manaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":228,"is_primary":true,"language_code":"my","name":"မာန်အောင်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":229,"is_primary":false,"language_code":"und","name":"Munaung;Manaung","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"Munaung;Manaung","boundary":"administrative","name":"မာန်အောင်မြို့နယ်","name:en":"Manaung Township","name:my":"မာန်အောင်မြို့နယ်","wikidata":"Q17065642","wikipedia":"en:Manaung Township"},"wikidata":"Q17065642","wikipedia":"en:Manaung Township"},"parent_id":7108,"public_id":"02024cd8-8421-4c25-8e3f-bd6ecf574ed5","reference_source":null,"slug":"osm:R:5996745","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":226,"is_primary":true,"language_code":"und","name":"မာန်အောင်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":227,"is_primary":true,"language_code":"en","name":"Manaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":228,"is_primary":true,"language_code":"my","name":"မာန်အောင်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":11584,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996745","id":229,"is_primary":false,"language_code":"und","name":"Munaung;Manaung","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996745","raw_id":9556,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996745","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":9556,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"80","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 5199;
    v_expected_name constant text := 'ကျောက်ဖြူ';
    v_mimu_pcode constant text := 'MMR012011';
    v_expected_parent_id constant bigint := 7185;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '42b5cd8cc1e4e0591004e41e7ae599e5';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ကျောက်ဖြူ","centroid":{"coordinates":[93.75918820309141,19.43363135],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996666","geometry_source":null,"id":5199,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Kyaukpyu","area_m2":1169359924.531223,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":561,"is_primary":true,"language_code":"und","name":"ကျောက်ဖြူ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":562,"is_primary":true,"language_code":"en","name":"Kyaukpyu Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":563,"is_primary":false,"language_code":"und","name":"Kyaukpyu","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Kyaukpyu","boundary":"administrative","name":"ကျောက်ဖြူ","name:en":"Kyaukpyu Township","wikidata":"Q6450780","wikipedia":"en:Kyaukpyu Township"},"wikidata":"Q6450780","wikipedia":"en:Kyaukpyu Township"},"parent_id":7185,"public_id":"c25fa666-5a35-4e95-af46-319665641346","reference_source":null,"slug":"osm:R:5996666","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":561,"is_primary":true,"language_code":"und","name":"ကျောက်ဖြူ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":562,"is_primary":true,"language_code":"en","name":"Kyaukpyu Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":563,"is_primary":false,"language_code":"und","name":"Kyaukpyu","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996666","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11716,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"197","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6897;
    v_expected_name constant text := 'မြေပုံ';
    v_mimu_pcode constant text := 'MMR012006';
    v_expected_parent_id constant bigint := 7005;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '95ee6ec3da390e8a68a1e37f16100f04';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မြေပုံ","centroid":{"coordinates":[93.537769989,20.06453735],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996752","geometry_source":null,"id":6897,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Myebon","area_m2":1968813044.571253,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5784,"is_primary":true,"language_code":"und","name":"မြေပုံ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5785,"is_primary":true,"language_code":"en","name":"Myebon Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5786,"is_primary":false,"language_code":"und","name":"Myebon","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Myebon","boundary":"administrative","name":"မြေပုံ","name:en":"Myebon Township","wikidata":"Q6947278","wikipedia":"en:Myebon Township"},"wikidata":"Q6947278","wikipedia":"en:Myebon Township"},"parent_id":7005,"public_id":"ba2d7ed8-46c2-4600-82b0-2ce891dea030","reference_source":null,"slug":"osm:R:5996752","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5784,"is_primary":true,"language_code":"und","name":"မြေပုံ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5785,"is_primary":true,"language_code":"en","name":"Myebon Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5786,"is_primary":false,"language_code":"und","name":"Myebon","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996752","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11743,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1896","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6950;
    v_expected_name constant text := 'မင်းပြား';
    v_mimu_pcode constant text := 'MMR012005';
    v_expected_parent_id constant bigint := 7005;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '7e0ee670229f21114e7737337c6eec8c';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မင်းပြား","centroid":{"coordinates":[93.520913555,20.54870525],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996714","geometry_source":null,"id":6950,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Minbya","area_m2":3420998007.473623,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5952,"is_primary":true,"language_code":"und","name":"မင်းပြား","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5953,"is_primary":true,"language_code":"en","name":"Minbya Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5954,"is_primary":false,"language_code":"und","name":"Minbya","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Minbya","boundary":"administrative","name":"မင်းပြား","name:en":"Minbya Township","wikidata":"Q6863310","wikipedia":"en:Minbya Township"},"wikidata":"Q6863310","wikipedia":"en:Minbya Township"},"parent_id":7005,"public_id":"21053ec0-3c86-497e-9aed-d82667ca8b8a","reference_source":null,"slug":"osm:R:5996714","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5952,"is_primary":true,"language_code":"und","name":"မင်းပြား","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5953,"is_primary":true,"language_code":"en","name":"Minbya Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5954,"is_primary":false,"language_code":"und","name":"Minbya","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996714","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11454,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1949","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6951;
    v_expected_name constant text := 'မြောက်ဦး';
    v_mimu_pcode constant text := 'MMR012003';
    v_expected_parent_id constant bigint := 7005;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'fb0299a84a4e267ca61b1afacd28748a';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မြောက်ဦး","centroid":{"coordinates":[93.17012433699182,20.61451045],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996743","geometry_source":null,"id":6951,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Mrauk-U","area_m2":1235162766.4775283,"boundary":"administrative","level_correction_applied":false,"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13454,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996743","id":5955,"is_primary":true,"language_code":"und","name":"မြောက်ဦး","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996743","raw_id":11455,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13454,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996743","id":5956,"is_primary":true,"language_code":"en","name":"Mrauk-U Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996743","raw_id":11455,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13454,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996743","id":5957,"is_primary":false,"language_code":"und","name":"Mrauk-U","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996743","raw_id":11455,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Mrauk-U","boundary":"administrative","name":"မြောက်ဦး","name:en":"Mrauk-U Township","wikidata":"Q6929522","wikipedia":"en:Mrauk-U Township"},"wikidata":"Q6929522","wikipedia":"en:Mrauk-U Township"},"parent_id":7005,"public_id":"9507bdfe-ed00-46b7-9f9e-e4ec83debe07","reference_source":null,"slug":"osm:R:5996743","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13454,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996743","id":5955,"is_primary":true,"language_code":"und","name":"မြောက်ဦး","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996743","raw_id":11455,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13454,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996743","id":5956,"is_primary":true,"language_code":"en","name":"Mrauk-U Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996743","raw_id":11455,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13454,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996743","id":5957,"is_primary":false,"language_code":"und","name":"Mrauk-U","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996743","raw_id":11455,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996743","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11455,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1950","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6960;
    v_expected_name constant text := 'ကျောက်တော်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR012004';
    v_expected_parent_id constant bigint := 7005;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'f803d4c8694c40f581c0825941896b46';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ကျောက်တော်မြို့နယ်","centroid":{"coordinates":[92.96369655802943,20.9024742],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996671","geometry_source":null,"id":6960,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Kyauktaw","area_m2":1703280220.5239847,"boundary":"administrative","level_correction_applied":false,"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13463,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996671","id":5982,"is_primary":true,"language_code":"und","name":"ကျောက်တော်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996671","raw_id":11464,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13463,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996671","id":5983,"is_primary":true,"language_code":"en","name":"Kyauktaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996671","raw_id":11464,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13463,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996671","id":5984,"is_primary":false,"language_code":"und","name":"Kyauktaw","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996671","raw_id":11464,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Kyauktaw","boundary":"administrative","name":"ကျောက်တော်","name:en":"Kyauktaw Township","wikidata":"Q6450800","wikipedia":"en:Kyauktaw Township"},"wikidata":"Q6450800","wikipedia":"en:Kyauktaw Township"},"parent_id":7005,"public_id":"9ad7c7bd-8c9d-48ce-85a4-72b48a60c052","reference_source":null,"slug":"osm:R:5996671","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13463,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996671","id":5982,"is_primary":true,"language_code":"und","name":"ကျောက်တော်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996671","raw_id":11464,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13463,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996671","id":5983,"is_primary":true,"language_code":"en","name":"Kyauktaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996671","raw_id":11464,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13463,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996671","id":5984,"is_primary":false,"language_code":"und","name":"Kyauktaw","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996671","raw_id":11464,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996671","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11464,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1959","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6965;
    v_expected_name constant text := 'ဘူးသီးတောင်';
    v_mimu_pcode constant text := 'MMR012010';
    v_expected_parent_id constant bigint := 6967;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '492ea6372637b8b3c2f34614096c4055';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ဘူးသီးတောင်","centroid":{"coordinates":[92.54131621318032,20.9895873],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996583","geometry_source":null,"id":6965,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","area_m2":2230349942.0347195,"boundary":"administrative","level_correction_applied":false,"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5997,"is_primary":true,"language_code":"und","name":"ဘူးသီးတောင်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5998,"is_primary":true,"language_code":"en","name":"Buthidaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5999,"is_primary":false,"language_code":"und","name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","boundary":"administrative","name":"ဘူးသီးတောင်","name:en":"Buthidaung Township","wikidata":"Q5002516","wikipedia":"en:Buthidaung Township"},"wikidata":"Q5002516","wikipedia":"en:Buthidaung Township"},"parent_id":6967,"public_id":"775b6bc4-da21-4482-b9b3-c6f3f34965f1","reference_source":null,"slug":"osm:R:5996583","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5997,"is_primary":true,"language_code":"und","name":"ဘူးသီးတောင်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5998,"is_primary":true,"language_code":"en","name":"Buthidaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5999,"is_primary":false,"language_code":"und","name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996583","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11470,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1964","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6966;
    v_expected_name constant text := 'မောင်တောမြို့နယ်';
    v_mimu_pcode constant text := 'MMR012009';
    v_expected_parent_id constant bigint := 6967;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '6d0c6ebf29c7269a4b237aedae05b33c';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မောင်တောမြို့နယ်","centroid":{"coordinates":[92.31205432236422,20.966861350000002],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996705","geometry_source":null,"id":6966,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":1460324081.3759391,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6000,"is_primary":true,"language_code":"und","name":"မောင်တော","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6001,"is_primary":true,"language_code":"en","name":"Maungdaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","boundary":"administrative","name":"မောင်တော","name:en":"Maungdaw Township","wikidata":"Q6792576","wikipedia":"en:Maungdaw Township"},"wikidata":"Q6792576","wikipedia":"en:Maungdaw Township"},"parent_id":6967,"public_id":"6620e7fe-f387-484d-8ebb-58f02975674e","reference_source":null,"slug":"osm:R:5996705","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6000,"is_primary":true,"language_code":"und","name":"မောင်တော","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6001,"is_primary":true,"language_code":"en","name":"Maungdaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"}],"osm_feature_type":"R","osm_id":"5996705","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11471,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1965","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6986;
    v_expected_name constant text := 'ရသေ့တောင်';
    v_mimu_pcode constant text := 'MMR012008';
    v_expected_parent_id constant bigint := 6988;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '67d8c16e55e80f9bc30bf0a6155fc289';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ရသေ့တောင်","centroid":{"coordinates":[92.68520796005728,20.45336955],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996815","geometry_source":null,"id":6986,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Rathedaung","area_m2":835801390.1872782,"boundary":"administrative","level_correction_applied":false,"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13489,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996815","id":6048,"is_primary":true,"language_code":"und","name":"ရသေ့တောင်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996815","raw_id":11490,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13489,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996815","id":6049,"is_primary":true,"language_code":"en","name":"Rathedaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996815","raw_id":11490,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13489,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996815","id":6050,"is_primary":false,"language_code":"und","name":"Rathedaung","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996815","raw_id":11490,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Rathedaung","boundary":"administrative","name":"ရသေ့တောင်","name:en":"Rathedaung Township","wikidata":"Q7295625","wikipedia":"en:Rathedaung Township"},"wikidata":"Q7295625","wikipedia":"en:Rathedaung Township"},"parent_id":6988,"public_id":"9ed96ae9-faa6-4198-9e03-b8db24ee490f","reference_source":null,"slug":"osm:R:5996815","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13489,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996815","id":6048,"is_primary":true,"language_code":"und","name":"ရသေ့တောင်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996815","raw_id":11490,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13489,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996815","id":6049,"is_primary":true,"language_code":"en","name":"Rathedaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996815","raw_id":11490,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13489,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996815","id":6050,"is_primary":false,"language_code":"und","name":"Rathedaung","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996815","raw_id":11490,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996815","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11490,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1985","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6987;
    v_expected_name constant text := 'ပုဏ္ဏားကျွန်း';
    v_mimu_pcode constant text := 'MMR012002';
    v_expected_parent_id constant bigint := 6988;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '574847af35734d245284f6d54e7b8181';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ပုဏ္ဏားကျွန်း","centroid":{"coordinates":[92.91591932143845,20.60841045],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996805","geometry_source":null,"id":6987,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Ponnagyun","area_m2":1126712685.0786989,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13490,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996805","id":6051,"is_primary":true,"language_code":"und","name":"ပုဏ္ဏားကျွန်း","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996805","raw_id":11492,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13490,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996805","id":6052,"is_primary":true,"language_code":"en","name":"Ponnagyun Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996805","raw_id":11492,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13490,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996805","id":6053,"is_primary":false,"language_code":"und","name":"Ponnagyun","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996805","raw_id":11492,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Ponnagyun","boundary":"administrative","name":"ပုဏ္ဏားကျွန်း","name:en":"Ponnagyun Township","wikidata":"Q7227890","wikipedia":"en:Ponnagyun Township"},"wikidata":"Q7227890","wikipedia":"en:Ponnagyun Township"},"parent_id":6988,"public_id":"bcd4d504-e27d-4861-b036-b4b857ff89d4","reference_source":null,"slug":"osm:R:5996805","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13490,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996805","id":6051,"is_primary":true,"language_code":"und","name":"ပုဏ္ဏားကျွန်း","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996805","raw_id":11492,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13490,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996805","id":6052,"is_primary":true,"language_code":"en","name":"Ponnagyun Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996805","raw_id":11492,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13490,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996805","id":6053,"is_primary":false,"language_code":"und","name":"Ponnagyun","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996805","raw_id":11492,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996805","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11492,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1986","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6993;
    v_expected_name constant text := 'စစ်တွေမြို့နယ်';
    v_mimu_pcode constant text := 'MMR012001';
    v_expected_parent_id constant bigint := 6988;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'ef0c1290203e1c546df31a0185e8f1bc';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"စစ်တွေမြို့နယ်","centroid":{"coordinates":[92.83780914604992,20.20743675],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996834","geometry_source":null,"id":6993,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Sittwe","area_m2":220701357.69673514,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13496,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996834","id":6069,"is_primary":true,"language_code":"und","name":"စစ်တွေမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996834","raw_id":11502,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13496,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996834","id":6070,"is_primary":true,"language_code":"en","name":"Sittwe Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996834","raw_id":11502,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13496,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996834","id":6071,"is_primary":true,"language_code":"my","name":"စစ်တွေမြို့နယ်","name_type":"official","n