-- Autonomous township remaining-gap repair: MMR016 / Shan (East)
-- Project locghyuranqaqsnbxflc; generated 2026-07-24.
-- One-time repair: existing geom only; no inserts or metadata changes.
BEGIN;
SET LOCAL statement_timeout = '15min';
SET LOCAL lock_timeout = '30s';

CREATE TEMP TABLE _autonomous_fill_results (
    township_id bigint PRIMARY KEY,
    canonical_name text NOT NULL,
    mimu_pcode text NOT NULL,
    status text NOT NULL CHECK (
        status IN ('updated', 'already_covered', 'numerical_residue', 'failed')
    ),
    best_candidate_id bigint,
    best_score double precision,
    second_score double precision,
    area_added_m2 double precision NOT NULL DEFAULT 0,
    new_overlap_m2 double precision NOT NULL DEFAULT 0,
    reason text NOT NULL
) ON COMMIT DROP;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6331;
    v_expected_name constant text := 'မိုင်းခတ်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR016002';
    v_expected_parent_id constant bigint := 6361;
    v_expected_state_id constant bigint := 6329;
    v_expected_geom_hash constant text := '00536cbaac6e1113beefd09a5fd8186f';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မိုင်းခတ်မြို့နယ်","centroid":{"coordinates":[99.31697918975037,21.693025900000002],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996730","geometry_source":null,"id":6331,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Mongkhet;Mong Khet","area_m2":2506768595.2879233,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3984,"is_primary":true,"language_code":"und","name":"မိုင်းခတ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3985,"is_primary":true,"language_code":"en","name":"Mong Khet Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3986,"is_primary":true,"language_code":"my","name":"မိုင်းခတ်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3987,"is_primary":false,"language_code":"und","name":"Mongkhet;Mong Khet","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"Mongkhet;Mong Khet","boundary":"administrative","name":"မိုင်းခတ်","name:en":"Mong Khet Township","name:my":"မိုင်းခတ်မြို့နယ်","wikidata":"Q6899402","wikipedia":"en:Mong Khet Township"},"wikidata":"Q6899402","wikipedia":"en:Mong Khet Township"},"parent_id":6361,"public_id":"946c6529-d6ec-414d-ba51-0a494d775522","reference_source":null,"slug":"osm:R:5996730","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3984,"is_primary":true,"language_code":"und","name":"မိုင်းခတ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3985,"is_primary":true,"language_code":"en","name":"Mong Khet Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3986,"is_primary":true,"language_code":"my","name":"မိုင်းခတ်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":12834,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996730","id":3987,"is_primary":false,"language_code":"und","name":"Mongkhet;Mong Khet","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996730","raw_id":10825,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996730","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":10825,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1330","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6338;
    v_expected_name constant text := 'မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)';
    v_mimu_pcode constant text := 'MMR016003';
    v_expected_parent_id constant bigint := 6325;
    v_expected_state_id constant bigint := 6329;
    v_expected_geom_hash constant text := '3368b030de31d99e44446d0ed165b68f';
    v_expected_other constant jsonb := '{"address_confidence_score":85,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":85,"boundary_note":null,"boundary_status":"surveyed","canonical_name":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)","centroid":{"coordinates":[99.79326720953833,21.872917682715553],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:18911818","geometry_source":"coremap_manual","id":6338,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","area_m2":19890497.41725971,"boundary":"administrative","level_correction_applied":true,"manual_boundary_correction":true,"manual_fix_type":"replace_existing","manual_gap_id":1,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":12841,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:18911818","id":4009,"is_primary":true,"language_code":"und","name":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"18911818","raw_id":10831,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12841,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:18911818","id":4010,"is_primary":true,"language_code":"en","name":"Mong Yang Township (de facto)","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"18911818","raw_id":10831,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12841,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:18911818","id":4011,"is_primary":true,"language_code":"my","name":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"18911818","raw_id":10831,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","boundary":"administrative","name":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)","name:en":"Mong Yang Township (de facto)","name:my":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)"}},"parent_id":6325,"public_id":"13bee3ab-42f0-4345-aaa6-d99507d72c18","reference_source":"mimu_v9_4_reference_only","slug":"osm:R:18911818","source_license_status":"open_confirmed","source_refs":{"entity_family":"admin_areas","manual_gap1_fix":{"fix_type":"replace_existing","gap_id":1,"note":null,"ref_note":"MIMU reference only, not copied","source":"Manual","updated_at":"2026-06-29T09:06:28.687598+00:00"},"names":[{"admin_area_candidate_id":12841,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:18911818","id":4009,"is_primary":true,"language_code":"und","name":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"18911818","raw_id":10831,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12841,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:18911818","id":4010,"is_primary":true,"language_code":"en","name":"Mong Yang Township (de facto)","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"18911818","raw_id":10831,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12841,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:18911818","id":4011,"is_primary":true,"language_code":"my","name":"မိုင်းယန်းမြို့နယ် (အမှန်တကယ်)","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"18911818","raw_id":10831,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"}],"osm_feature_type":"R","osm_id":"18911818","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":10831,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1337","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":2,"verification_note":"Manual gap 1 township boundary correction. MIMU used only as reference, not copied. ","verification_status":"needs_fix","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_live_area_m2 double precision;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_expected_name, v_mimu_pcode, 'failed',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other
       OR md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash
       OR v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'production row changed after the verified local backup');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'current geometry is empty, invalid, or has the wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR ST_SRID(v_mimu) <> 4326 THEN
        INSERT INTO _autonomous_fill_results
            (township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
             'normalized MIMU township geometry is unusable');
        RETURN;
    END IF;

    -- Re-rank against the current live database immediately before the write.
    -- Names make no contribution. The plan recipient must remain the strongest
    -- overall geometry-first representative; no score-margin threshold is used.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    measured AS (
        SELECT
            base.*,
            ST_Distance(
                ST_Transform(v_mimu, 6933),
                ST_Transform(base.geom, 6933)
            ) AS distance_m
        FROM candidate_base AS base
    ),
    scored AS (
        SELECT
            measured.id,
            measured.intersection_m2,
            measured.distance_m,
            (
                30.0 * LEAST(
                    1.0, measured.intersection_m2 / NULLIF(measured.core_area_m2, 0)
                )
                + 25.0 * (
                    measured.intersection_m2
                    / NULLIF(sum(measured.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    measured.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (
                        measured.core_pos_in_mimu::int
                        + measured.mimu_pos_in_core::int
                    ) / 2.0
                )
                + 4.0 * CASE
                    WHEN measured.parent_id = v_expected_parent_id THEN 1 ELSE 0
                  END
                + 2.0 * CASE
                    WHEN measured.state_id = v_expected_state_id THEN 1 ELSE 0
                  END
                + 18.0 * exp(-measured.distance_m / 1000.0)
            ) AS score
        FROM measured
    ),
    ranked AS (
        SELECT
            id,
            score,
            row_number() OVER (
                ORDER BY score DESC, intersection_m2 DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0)
    INTO v_best_candidate_id, v_best_score, v_second_score
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, coalesce(v_best_score, 0),
            coalesce(v_second_score, 0),
            'planned recipient is no longer the strongest live spatial representative'
        );
        RETURN;
    END IF;

    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    -- This is the complete current uncovered portion of this one MIMU township.
    -- It is never the full source polygon unless the entire source is uncovered.
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'already_covered',
            v_best_candidate_id, v_best_score, v_second_score,
            'source township became fully covered by an earlier live patch'
        );
        RETURN;
    END IF;
    v_live_area_m2 := ST_Area(ST_Transform(v_live_patch, 6933));
    IF v_live_area_m2 <= 1.0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode,
            'numerical_residue', v_best_candidate_id, v_best_score,
            v_second_score,
            format('uncovered source residue is only %s m2', v_live_area_m2)
        );
        RETURN;
    END IF;

    -- Use the exact live patch and the explicit topological union requested for
    -- this repair. No source polygon replaces the current row.
    v_safe_patch := v_live_patch;
    v_boundary_collar_m2 := 0;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_UnaryUnion(ST_Collect(v_before.geom, v_safe_patch)),
            3
        )
    );
    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score,
            'verbatim old geometry plus collared patch is not a valid MultiPolygon'
        );
        RETURN;
    END IF;
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := v_live_area_m2;
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_live_patch, v_mimu), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Intersection(v_live_patch, v_current_union),
                    3
                ),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_live_patch, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 <= 0 THEN
        INSERT INTO _autonomous_fill_results (
            township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_target_id, v_before.canonical_name, v_mimu_pcode, 'failed',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'geometry validation failed: removed=%s outside_mimu=%s precovered=%s overlap=%s collar=%s',
                v_removed_m2, v_outside_mimu_m2, v_precovered_m2,
                v_new_overlap_m2, v_boundary_collar_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR coalesce(
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Difference(v_before.geom, v_after.geom), 3),
                    6933
                )
            ),
            0
          ) > 1.0
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Township % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _autonomous_fill_results (
        township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        format(
            'current MIMU-source gap added by topological union; collar=%s m2',
            v_boundary_collar_m2
        )
    );
END
$autonomous_fill$;

DO $autonomous_fill$
DECLARE
    v_target_id constant bigint := 6360;
    v_expected_name constant text := 'ကျိုင်းတုံမြို့နယ်';
    v_mimu_pcode constant text := 'MMR016001';
    v_expected_parent_id constant bigint := 6361;
    v_expected_state_id constant bigint := 6329;
    v_expected_geom_hash constant text := '4279c3b277ca169118adc5e66d1ad543';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ကျိုင်းတုံမြို့နယ်","centroid":{"coordinates":[99.64263390855811,21.26274475],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996650","geometry_source":null,"id":6360,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Kengtung;Keng Tung;ကျိုင်းတုံ","area_m2":3509725892.2842364,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":12863,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996650","id":4075,"is_primary":true,"language_code":"und","name":"ကျိုင်းတုံမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996650","raw_id":10852,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12863,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996650","id":4076,"is_primary":true,"language_code":"en","name":"Kengtung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996650","raw_id":10852,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12863,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996650","id":4077,"is_primary":true,"language_code":"my","name":"ကျိုင်းတ